{"implementation":"import math


def _require_finite_number(value, field):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(field + " must be a number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(field + " must be finite")
    return value


def api_call_loss_filter(payload):
    if not isinstance(payload, dict):
        raise ValueError("case payload must be an object")
    if "threshold" not in payload or "calls" not in payload:
        raise ValueError("case payload requires threshold and calls")

    threshold = _require_finite_number(payload["threshold"], "threshold")
    if threshold < 0:
        raise ValueError("threshold must be nonnegative")

    calls = payload["calls"]
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    validated = []
    seen_ids = set()
    for position, call in enumerate(calls):
        prefix = "calls[" + str(position) + "]"
        if not isinstance(call, dict):
            raise ValueError(prefix + " must be an object")
        required = (
            "call_id",
            "loss_without_call",
            "loss_with_call",
            "prediction_tokens",
            "parseable",
        )
        for field in required:
            if field not in call:
                raise ValueError(prefix + " requires " + field)

        call_id = call["call_id"]
        if not isinstance(call_id, str) or not call_id:
            raise ValueError(prefix + ".call_id must be a nonempty string")
        if call_id in seen_ids:
            raise ValueError("call_id values must be unique")
        seen_ids.add(call_id)

        loss_without = _require_finite_number(
            call["loss_without_call"], prefix + ".loss_without_call"
        )
        loss_with = _require_finite_number(
            call["loss_with_call"], prefix + ".loss_with_call"
        )
        if loss_without < 0 or loss_with < 0:
            raise ValueError("loss values must be nonnegative")

        prediction_tokens = call["prediction_tokens"]
        if (
            isinstance(prediction_tokens, bool)
            or not isinstance(prediction_tokens, int)
            or prediction_tokens < 0
        ):
            raise ValueError(prefix + ".prediction_tokens must be a nonnegative integer")

        parseable = call["parseable"]
        if not isinstance(parseable, bool):
            raise ValueError(prefix + ".parseable must be a boolean")

        validated.append(
            (call_id, loss_without, loss_with, prediction_tokens, parseable)
        )

    diagnostics = []
    accepted_call_ids = []
    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        denominator = max(1, prediction_tokens)
        normalized_weight = 1.0 / denominator
        weighted_loss_without = loss_without * normalized_weight
        weighted_loss_with = loss_with * normalized_weight
        normalized_gain = weighted_loss_without - weighted_loss_with
        accepted = parseable and normalized_gain >= threshold

        diagnostic = {
            "call_id": call_id,
            "normalized_weight": round(normalized_weight, 8),
            "weighted_loss_without_call": round(weighted_loss_without, 8),
            "weighted_loss_with_call": round(weighted_loss_with, 8),
            "normalized_gain": round(normalized_gain, 8),
            "parseable": parseable,
            "accepted": accepted,
        }
        diagnostics.append(diagnostic)
        if diagnostic["accepted"]:
            accepted_call_ids.append(diagnostic["call_id"])

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    payload = case
    if "calls" not in case and "payload" in case:
        payload = case["payload"]
    return api_call_loss_filter(payload)
